using System.Collections.Generic;
using UnityEngine;

namespace MutantPlants
{
    /// <summary>
    /// Spawns particle effects. The particle prefabs live in Resources/FX
    /// (generated by the Mutant Plants builder) so they are always included in builds.
    /// </summary>
    public static class FX
    {
        public const string Splat = "Splat";
        public const string Explosion = "Explosion";
        public const string Dust = "Dust";
        public const string Impact = "Impact";
        public const string MuzzleFlash = "MuzzleFlash";
        public const string Shockwave = "Shockwave";
        public const string Sparkle = "Sparkle";

        const int IgnoreRaycastLayer = 2;
        static readonly Dictionary<string, GameObject> cache = new Dictionary<string, GameObject>();

        public static GameObject Spawn(string name, Vector3 position, Quaternion rotation, Color? color = null, float scale = 1f, Transform parent = null)
        {
            if (!cache.TryGetValue(name, out var prefab) || prefab == null)
            {
                prefab = Resources.Load<GameObject>("FX/" + name);
                cache[name] = prefab;
            }
            if (prefab == null) return null;

            var go = Object.Instantiate(prefab, position, rotation, parent);
            if (scale != 1f) go.transform.localScale *= scale;
            foreach (var ps in go.GetComponentsInChildren<ParticleSystem>())
            {
                if (color.HasValue)
                {
                    var main = ps.main;
                    var c = color.Value;
                    main.startColor = new ParticleSystem.MinMaxGradient(c, Color.Lerp(c, Color.white, 0.25f));
                }
                ps.Play();
            }
            Object.Destroy(go, 4f);
            return go;
        }

        public static GameObject Spawn(string name, Vector3 position, Color? color = null, float scale = 1f) =>
            Spawn(name, position, Quaternion.identity, color, scale);

        /// <summary>Physics chunks flying off (death splat).</summary>
        public static void Chunks(Vector3 position, Material material, int count, float size, float force = 3f)
        {
            for (int i = 0; i < count; i++)
            {
                var chunk = GameObject.CreatePrimitive(i % 2 == 0 ? PrimitiveType.Cube : PrimitiveType.Sphere);
                chunk.name = "Chunk";
                chunk.layer = IgnoreRaycastLayer;
                chunk.transform.position = position + Random.insideUnitSphere * 0.3f;
                chunk.transform.rotation = Random.rotation;
                chunk.transform.localScale = Vector3.one * size * Random.Range(0.5f, 1.2f);
                var r = chunk.GetComponent<Renderer>();
                r.sharedMaterial = material;
                r.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;

                var rb = chunk.AddComponent<Rigidbody>();
                rb.mass = 0.1f;
                rb.AddForce((Random.insideUnitSphere + Vector3.up * 1.2f) * Random.Range(force * 0.6f, force * 1.3f), ForceMode.Impulse);
                rb.AddTorque(Random.insideUnitSphere * 2f, ForceMode.Impulse);
                chunk.AddComponent<ShrinkAndDie>().lifetime = Random.Range(1.5f, 2.5f);
            }
        }
    }

    /// <summary>Scales an object down to nothing, then destroys it.</summary>
    public class ShrinkAndDie : MonoBehaviour
    {
        public float lifetime = 2f;
        float age;
        Vector3 startScale;

        void Start() => startScale = transform.localScale;

        void Update()
        {
            age += Time.deltaTime;
            float k = age / lifetime;
            if (k > 0.6f) transform.localScale = startScale * Mathf.Clamp01(1f - (k - 0.6f) / 0.4f);
            if (k >= 1f) Destroy(gameObject);
        }
    }
}
